import{z as l,x as o,o as i,c as p,q as n,j as A,D as e,d as E,s,S as t,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"技能溢价与 Tinbergen 竞赛","description":"","frontmatter":{"title":"技能溢价与 Tinbergen 竞赛","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/skill-premium-tinbergen.md","filePath":"econ/skill-premium-tinbergen.md","lastUpdated":1791413859000}'),m={name:"econ/skill-premium-tinbergen.md"};function d(g,a,c,D,C,_){const r=o("Mermaid");return i(),p("div",null,[a[2]||(a[2]=n('<h1 id="技能溢价与-tinbergen-竞赛" tabindex="-1">技能溢价与 Tinbergen 竞赛 <a class="header-anchor" href="#技能溢价与-tinbergen-竞赛" aria-label="Permalink to &quot;技能溢价与 Tinbergen 竞赛&quot;">​</a></h1><div class="epigraph"><p>不平等的走向由一场竞赛决定：教育在一边扩大供给，技术在另一边拉高需求。</p><footer>—— 据 Tinbergen, Income Distribution: Analysis and Policies, 1975；Katz and Murphy, Changes in Relative Wages, 1963–1987: Supply and Demand Factors, QJE, 1992 整理</footer></div><p><a href="/econ/human-capital-becker">上一课</a>解释了个人为什么投资教育与培训、剖面为什么凹，但把教育回报 \\(\\rho\\) 当成了给定参数。缺口是市场层面的问题：大学毕业生对高中毕业生的工资溢价，为什么 1970 年代回落、1980 年代起大幅走阔？本课讲 Tinbergen 的「教育与技术竞赛」与 Katz–Murphy 的供需框架：把劳动切成技能两组，用 CES 聚合把「技术偏向」从一个形容词变成参数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\rho\\) 是个体回归系数；溢价是相对价格，供给与需求两条线都在动。美国的形态：1970 年代大学溢价回落——战后婴儿潮与大学扩招把技能相对供给推大；1980 年代起溢价陡升，供给仍在增长，涨得更快的只能是需求侧。缺口是给这两条线一个共同的账本，能分解出供给贡献多少、需求贡献多少。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SB 模型（Katz–Murphy 1992 的口径）：技能与非技能劳动进 CES 聚合，</p> \\[Y = \\Big[(A_S L_S)^{\\frac{\\sigma-1}{\\sigma}} + (A_U L_U)^{\\frac{\\sigma-1}{\\sigma}}\\Big]^{\\frac{\\sigma}{\\sigma-1}}, \\]<p>技能溢价由一阶条件直接写出：</p> \\[\\frac{w_S}{w_U} = \\left(\\frac{A_S}{A_U}\\right)^{\\frac{\\sigma-1}{\\sigma}} \\left(\\frac{L_S}{L_U}\\right)^{-\\frac{1}{\\sigma}} . \\]<p><span class="marginnote">术语翻译：「CES 聚合」就是「带一个旋钮 \\(\\sigma\\) 的混合公式」，旋钮控制两类劳动有多容易互相替换——\\(\\sigma\\to\\infty\\) 时二者完全互换，\\(\\sigma\\) 有限时谁也顶不掉谁。Katz–Murphy 估出 \\(\\sigma\\approx 1.4\\)，意思是大学生与高中生「像但不完全像」同一种投入。</span></p><p>读法：相对供给 \\(L_S/L_U\\) 上升压低溢价，弹性 \\(-1/\\sigma\\)；技能相对效率 \\(A_S/A_U\\) 上升抬高溢价——这就是技能偏向的技术进步（SBTC）。\\(\\sigma\\) 用相对工资与相对供给的时间序列联合估出，Katz–Murphy 的估计在 1.4 上下：替代不完全，供给扩张平滑不掉需求冲击。分解由此可行：1970 年代的回落几乎全是供给项（婴儿潮队列涌入大学毕业生市场），1980 年代的走阔供给解释不动，需求项必须正增长——技术的偏向被反推出来。</p><p><span class="marginnote">数字实例：取 \\(\\sigma=1.4\\)，则 \\(-1/\\sigma\\approx-0.71\\)——大学毕业生相对供给每增加 10%，溢价约被压低 7%。若技能偏向项以每年 2% 的速度抬升，一年的供给压低效应两年就被需求覆盖；供给扩张再快，也追不上持续偏向的需求，这正是 1980 年代溢价走阔的账本。</span></p>',13)),(i(),A(t,null,{default:e(()=>[s(r,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDU%5B%22%E6%95%99%E8%82%B2%E4%BE%9B%E7%BB%99%EF%BC%9A%E9%98%9F%E5%88%97%E8%A7%84%E6%A8%A1%E3%80%81%E6%89%A9%E6%8B%9B%22%5D%20--%3E%20PREM%5B%22%E6%8A%80%E8%83%BD%E6%BA%A2%E4%BB%B7%20wS%2FwU%22%5D%0A%20%20TECH%5B%22%E6%8A%80%E6%9C%AF%EF%BC%9A%E4%BB%BB%E5%8A%A1%E6%9B%BF%E4%BB%A3%E4%B8%8E%E4%BA%92%E8%A1%A5%22%5D%20--%3E%20PREM%0A%20%20SUP%5B%22%E4%BE%9B%E7%BB%99%E9%A1%B9%EF%BC%9A%E7%9B%B8%E5%AF%B9%E4%BE%9B%E7%BB%99%E4%B8%8A%E5%8D%87%EF%BC%8C%E2%88%921%2F%CF%83%20%E5%8E%8B%E4%BD%8E%22%5D%20--%3E%20PREM%0A%20%20DEM%5B%22%E9%9C%80%E6%B1%82%E9%A1%B9%EF%BC%9A%E6%8A%80%E8%83%BD%E5%81%8F%E5%90%91%EF%BC%8C%E6%8A%AC%E9%AB%98%22%5D%20--%3E%20PREM%0A%20%20PREM%20--%3E%20RACE%5B%221970s%20%E5%9B%9E%E8%90%BD%EF%BC%88%E4%BE%9B%E7%BB%99%EF%BC%89%E2%86%92%201980s%20%E8%B5%B7%E8%B5%B0%E9%98%94%EF%BC%88%E9%9C%80%E6%B1%82%EF%BC%89%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[E("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,[E("技术为什么偏向技能：计算机替代可编码的例行任务，与问题解决、抽象任务互补——任务口径的证据见 Autor–Levy–Murnane 2003。偏向本身是内生的：本栏"),B("a",{href:"/econ/directed-technical-change"},"有偏技术进步"),E("的一般框架说，要素规模与价格反过来引导创新方向——大学毕业生越多，瞄准他们的技术越有人做。竞赛因此有两个速度：教育供给一个世代才变一次（人口与学制的节奏），技术需求每十年就能换一轮；1980 年代后美国的教育增速放缓，比分开始偏向技术。自动化补记：新近文献把「替代任务」与「新增任务」分开（Acemoglu–Restrepo 的任务模型），溢价上升不只读成技能偏向，也读成自动化净替代了中等技能的例行岗位——中间层次的空洞是两组模型之外的事实。")],-1)),(i(),A(t,null,{default:e(()=>[s(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20COMP%5B%22%E8%AE%A1%E7%AE%97%E6%9C%BA%E4%B8%8E%E8%87%AA%E5%8A%A8%E5%8C%96%22%5D%20--%3E%20ROUT%5B%22%E6%9B%BF%E4%BB%A3%3A%20%E5%8F%AF%E7%BC%96%E7%A0%81%E7%9A%84%E4%BE%8B%E8%A1%8C%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20ROUT%20--%3E%20MID%5B%22%E4%B8%AD%E7%AD%89%E6%8A%80%E8%83%BD%E5%B2%97%E4%BD%8D%E6%94%B6%E7%BC%A9%22%5D%0A%20%20COMP%20--%3E%20ABS%5B%22%E4%BA%92%E8%A1%A5%3A%20%E6%8A%BD%E8%B1%A1%E4%B8%8E%E9%97%AE%E9%A2%98%E8%A7%A3%E5%86%B3%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20ABS%20--%3E%20HIGH%5B%22%E9%AB%98%E6%8A%80%E8%83%BD%E9%9C%80%E6%B1%82%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HAND%5B%22%E4%B8%8D%E5%8F%AF%E7%BC%96%E7%A0%81%E7%9A%84%E4%BD%8E%E6%8A%80%E8%83%BD%E6%89%8B%E5%B7%A5%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20LOW%5B%22%E4%BD%8E%E7%AB%AF%E5%B2%97%E4%BD%8D%E7%95%99%E4%B8%8B%2C%20%E5%B7%A5%E8%B5%84%E9%9A%BE%E6%B6%A8%22%5D%0A%20%20MID%20--%3E%20HOLLOW%5B%22%E5%B0%B1%E4%B8%9A%E5%88%86%E5%B8%83%E4%B8%AD%E7%A9%BA%E5%8C%96%22%5D%0A%20%20HIGH%20--%3E%20HOLLOW%0A%20%20LOW%20--%3E%20HOLLOW%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">大学对高中的相对周薪溢价从 1970 年代末的低点走到 2000 年代，按 Goldin–Katz 的序列几乎翻倍：供给解释了 1970s 的回落，解释不了 1980s 的斜率——这是「竞赛」叙事的实证底盘，也是 SBTC 作为残差项被反推出来的方式。</span></p><p><span class="marginnote">常见误区：初学者容易把 SBTC 里的「T」当成观测到的技术数据。实际上它是从工资序列里反推的残差——同一时期最低工资被侵蚀、工会密度下降、贸易冲击都能产生相似的形状。把残差一律标成「技术」，再用它解释工资，就有循环论证的风险。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>两组模型把技能当一维，真实的是职业与任务的连续谱；「中空化」要任务口径才能说全。\\(\\sigma\\) 与 SBTC 在时间序列里难分家：两者都动相对需求，识别靠函数形式与外部证据，把残差一律标成「技术」有循环风险。也别把溢价全记在技术上：同一时期最低工资的实际值被侵蚀、工会密度下降、贸易冲击都在动相对工资——竞赛是主叙事，不是唯一叙事；把它当成唯一解释，会在制度变量上错归因。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SB 模型把溢价写成供需比：\\((A_S/A_U)^{(\\sigma-1)/\\sigma}(L_S/L_U)^{-1/\\sigma}\\)。</li><li>替代弹性有限（约 1.4），供给扩张平滑不掉需求冲击。</li><li>1970s 回落是供给（婴儿潮与扩招），1980s 起走阔要靠技能偏向的需求增长。</li><li>竞赛两速：教育一个世代一变，技术十年一变；自动化是新的第三只手。</li><li>出处：Tinbergen 1975；Katz and Murphy, QJE 1992；Goldin and Katz 2008；Autor, Levy and Murnane 2003。</li></ul>',6))])}const f=l(m,[["render",d]]);export{u as __pageData,f as default};
